import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Sequence,
  Img,
  staticFile,
} from "remotion";
import React from "react";

export const fps = 25;
export const durationInFrames = 500;

const tc = (seconds: number) => Math.round(seconds * 25);

const APIFY_ORANGE = "#FF6B35";
const APIFY_TEAL = "#00C9B1";
const APIFY_DARK = "#0D0D1A";

const FadeIn: React.FC<{ delay: number; children: React.ReactNode; direction?: "up" | "down" }> = ({ delay, children, direction = "up" }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = spring({ frame, fps, delay, config: { damping: 170, stiffness: 80 } });
  const yShift = direction === "up" ? 60 : -60;
  return (
    <div style={{ opacity: p, transform: `translateY(${interpolate(p, [0, 1], [yShift, 0])}px)` }}>
      {children}
    </div>
  );
};

const SpringIn: React.FC<{ delay: number; children: React.ReactNode; direction?: "up" | "left" | "right" | "scale" }> = ({ delay, children, direction = "scale" }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const p = spring({ frame, fps, delay, config: { damping: 180, stiffness: 80 } });
  let transform = "";
  if (direction === "up") transform = `translateY(${interpolate(p, [0, 1], [80, 0])}px)`;
  if (direction === "left") transform = `translateX(${interpolate(p, [0, 1], [-120, 0])}px)`;
  if (direction === "right") transform = `translateX(${interpolate(p, [0, 1], [120, 0])}px)`;
  if (direction === "scale") transform = `scale(${interpolate(p, [0, 1], [0.7, 1])})`;
  return (
    <div style={{ opacity: p, transform }}>
      {children}
    </div>
  );
};

// ── Scene 1: Particle implosion → logo lands ──────────────────────────────────
const SceneOne: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Logo entrance — big spring after particles converge
  const logoP = spring({ frame, fps, delay: 30, config: { damping: 160, stiffness: 55 } });
  const logoScale = interpolate(logoP, [0, 1], [4.5, 1]);
  const logoOpacity = logoP;

  // Subtle breathe after land
  const breathe = 1 + Math.sin(frame * 0.06) * 0.012;

  // Radial particles converging inward
  const particleCount = 48;
  const cx = 1920;
  const cy = 1080;

  const glowPulse = 0.7 + Math.sin(frame * 0.08) * 0.3;

  // Background grid opacity
  const bgP = spring({ frame, fps, delay: 0, config: { damping: 180, stiffness: 50 } });

  return (
    <AbsoluteFill style={{
      background: `radial-gradient(ellipse at 50% 48%, #1B1B35 0%, #080812 65%, #000008 100%)`,
      overflow: "hidden",
    }}>

      {/* Fine dot grid */}
      <svg style={{ position: "absolute", inset: 0, width: "100%", height: "100%" }} viewBox="0 0 3840 2160">
        <defs>
          <pattern id="dots" x="0" y="0" width="80" height="80" patternUnits="userSpaceOnUse">
            <circle cx="40" cy="40" r="1.5" fill={APIFY_TEAL} opacity="0.18" />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#dots)" opacity={bgP * 0.8} />
      </svg>

      {/* Converging particles */}
      <svg style={{ position: "absolute", inset: 0, width: "100%", height: "100%", overflow: "visible" }} viewBox="0 0 3840 2160">
        {Array.from({ length: particleCount }, (_, i) => {
          const angle = (i / particleCount) * Math.PI * 2;
          const startR = 900 + Math.sin(i * 2.3) * 300;
          const delay = i * 1.2;
          const p = spring({ frame, fps, delay, config: { damping: 90, stiffness: 35 } });
          const r = interpolate(p, [0, 1], [startR, 0]);
          const px = cx + Math.cos(angle) * r;
          const py = cy + Math.sin(angle) * r;
          const size = 8 + (i % 5) * 5;
          const opacity = interpolate(p, [0, 0.15, 0.85, 1], [0, 1, 0.8, 0]);
          const color = i % 3 === 0 ? APIFY_ORANGE : i % 3 === 1 ? APIFY_TEAL : "#FFFFFF";

          return (
            <circle key={i} cx={px} cy={py} r={size} fill={color} opacity={opacity}>
              <animate attributeName="opacity" values={`${opacity};${opacity * 0.5};${opacity}`} dur="0.6s" repeatCount="indefinite" />
            </circle>
          );
        })}

        {/* Radial sweep lines */}
        {Array.from({ length: 12 }, (_, i) => {
          const angle = (i / 12) * Math.PI * 2;
          const delay = i * 2;
          const p = spring({ frame, fps, delay, config: { damping: 100, stiffness: 40 } });
          const len = interpolate(p, [0, 1], [600, 0]);
          const x2 = cx + Math.cos(angle) * len;
          const y2 = cy + Math.sin(angle) * len;
          const opacity = interpolate(p, [0, 0.2, 0.9, 1], [0, 0.4, 0.3, 0]);
          const color = i % 2 === 0 ? APIFY_ORANGE : APIFY_TEAL;
          return (
            <line key={i} x1={cx} y1={cy} x2={x2} y2={y2}
              stroke={color} strokeWidth="1.5" opacity={opacity} />
          );
        })}
      </svg>

      {/* Glow halo behind logo */}
      <div style={{
        position: "absolute",
        left: cx - 700,
        top: cy - 700,
        width: 1400,
        height: 1400,
        borderRadius: "50%",
        background: `radial-gradient(circle, ${APIFY_ORANGE}28 0%, ${APIFY_TEAL}12 40%, transparent 70%)`,
        opacity: logoP * glowPulse,
        pointerEvents: "none",
      }} />

      {/* THE LOGO */}
      <div style={{
        position: "absolute",
        left: cx - 420,
        top: cy - 420,
        width: 840,
        height: 840,
        opacity: logoOpacity,
        transform: `scale(${logoScale * breathe})`,
        transformOrigin: "center center",
        filter: `drop-shadow(0 0 60px ${APIFY_ORANGE}99) drop-shadow(0 0 120px ${APIFY_ORANGE}44)`,
      }}>
        <Img src={staticFile("assets/Apify symbol colors.svg")} style={{ width: "100%", height: "100%", objectFit: "contain" }} />
      </div>

      {/* Outer ring that fades out as logo lands */}
      <svg style={{ position: "absolute", inset: 0, width: "100%", height: "100%", overflow: "visible" }} viewBox="0 0 3840 2160">
        <defs>
          <radialGradient id="ringGrad1">
            <stop offset="0%" stopColor={APIFY_ORANGE} stopOpacity="0.8" />
            <stop offset="100%" stopColor={APIFY_TEAL} stopOpacity="0.2" />
          </radialGradient>
        </defs>
        {[520, 640, 760].map((r, i) => {
          const rp = spring({ frame, fps, delay: 28 + i * 6, config: { damping: 140, stiffness: 55 } });
          const ringOpacity = interpolate(rp, [0, 0.5, 1], [0, 0.35, 0.08]);
          const dashOffset = frame * (i % 2 === 0 ? 1.2 : -0.8);
          return (
            <circle key={i} cx={cx} cy={cy} r={r}
              fill="none"
              stroke={i % 2 === 0 ? APIFY_ORANGE : APIFY_TEAL}
              strokeWidth={2 - i * 0.4}
              strokeDasharray={`${30 + i * 10} ${20 + i * 8}`}
              strokeDashoffset={dashOffset}
              opacity={ringOpacity}
            />
          );
        })}
      </svg>

    </AbsoluteFill>
  );
};

