        transformOrigin: "center center",
        filter: `drop-shadow(0 0 80px ${APIFY_ORANGE}AA) drop-shadow(0 0 200px ${APIFY_ORANGE}44) drop-shadow(0 0 40px ${APIFY_TEAL}66)`,
      }}>
        <Img src={staticFile("assets/Apify symbol colors.svg")} style={{ width: "100%", height: "100%", objectFit: "contain" }} />
      </div>

      {/* CTA block */}
      <div style={{
        position: "absolute",
        left: 0,
        right: 0,
        bottom: 220,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 40,
        opacity: ctaP,
        transform: `translateY(${interpolate(ctaP, [0, 1], [60, 0])}px)`,
      }}>
        <div style={{
          fontSize: 96,
          fontWeight: 900,
          letterSpacing: "0.25em",
          fontFamily: "system-ui, -apple-system, sans-serif",
          color: "#FFFFFF",
          textShadow: `0 0 80px ${APIFY_ORANGE}66, 0 0 160px ${APIFY_ORANGE}22`,
        }}>
          APIFY
        </div>

        <div style={{
          width: 500,
          height: 5,
          background: `linear-gradient(90deg, transparent, ${APIFY_ORANGE}, ${APIFY_TEAL}, transparent)`,
          borderRadius: 4,
          boxShadow: `0 0 20px ${APIFY_ORANGE}66`,
        }} />

        <div style={{
          fontSize: 52,
          fontWeight: 300,
          letterSpacing: "0.48em",
          fontFamily: "system-ui, -apple-system, sans-serif",
          color: APIFY_TEAL,
          textTransform: "uppercase",
        }}>
          The web is your dataset
        </div>
      </div>

      {/* apify.com badge */}
      <div style={{
        position: "absolute",
        bottom: 80,
        right: 140,
        opacity: badgeP,
        transform: `translateY(${interpolate(badgeP, [0, 1], [30, 0])}px)`,
        fontSize: 38,
        fontWeight: 600,
        letterSpacing: "0.15em",
        fontFamily: "system-ui, -apple-system, sans-serif",
        color: `${APIFY_ORANGE}AA`,
        textTransform: "uppercase",
      }}>
        apify.com
      </div>

      {/* Corner brackets */}
      {[0, 1, 2, 3].map((i) => {
        const cp = spring({ frame, fps, delay: i * 8, config: { damping: 170, stiffness: 80 } });
        const isTop = i < 2;
        const isLeft = i % 2 === 0;
        return (
          <div key={i} style={{
            position: "absolute",
            ...(isLeft ? { left: 100 } : { right: 100 }),
            ...(isTop ? { top: 100 } : { bottom: 100 }),
            width: 100,
            height: 100,
            opacity: cp * 0.55,
            borderTop: isTop ? `3px solid ${APIFY_ORANGE}` : "none",
            borderBottom: !isTop ? `3px solid ${APIFY_ORANGE}` : "none",
            borderLeft: isLeft ? `3px solid ${APIFY_ORANGE}` : "none",
            borderRight: !isLeft ? `3px solid ${APIFY_ORANGE}` : "none",
          }} />
        );
      })}

    </AbsoluteFill>
  );
};

